import sys
from collections import deque

def matches(a, b):
    if len(a) == 1 or len(b) == 1:
        return a in b or b in a
    return sum(x == y for x, y in zip(a, b)) == 2

lines = sys.stdin.read().splitlines()
tops = lines[0].split()
hand = lines[1].split()
draw = deque(' '.join(lines[2:]).split())
while True:
    chosen = None
    for i, card in enumerate(hand):
        for p in range(2):
            if matches(card, tops[p]):
                chosen = p
                tops[p] = hand.pop(i)
                break
        if chosen is not None:
            break
    if chosen is not None:
        while hand:
            for i, card in enumerate(hand):
                if matches(card, tops[chosen]):
                    tops[chosen] = hand.pop(i)
                    break
            else:
                break
    # Draw only after a complete turn, retaining hand order.
    added = 0
    while draw and len(hand) < 7:
        hand.append(draw.popleft())
        added += 1
    if chosen is None and added == 0:
        break
print(len(hand), *tops)
